(* [comment removed for export] *)
Lemma ASvcChain_off2 : forall m first L lo h r,
  ASvcChain m first L -> aceil <= lo ->
  Forall (fun e => se_addr e + 48 <= r \/ r + SZ_REG <= se_addr e) L ->
  Forall (fun e => disjoint_from [(lo, h); (r + O_REG_MUTEX, r + O_REG_MUTEX + 40)]%Z (se_addr e) 48) L.
Proof.
  intros m first L lo h r CH CE OFF. pose proof (ASvcChain_Forall _ _ _ CH) as FO. clear CH.
  induction L as [|e L IH]; [constructor|].
  pose proof (Forall_inv FO) as (POS & _ & AP & _). pose proof (Forall_inv OFF) as O1.
  pose proof (aapp_bounds _ _ AP ltac:(lia)) as (B1 & B2 & B3 & B4 & B5).
  constructor; [| apply IH; [exact (Forall_inv_tail OFF)| exact (Forall_inv_tail FO)]].
  unfold SZ_REG, O_REG_MUTEX in *. cbn [disjoint_from fst snd]. split; [left; lia|]. split; [lia| exact I].
Qed.
